/** Frame-based scroll renderer: no video seeks or decoder resets. */
export class StoryPlayer {
 constructor({videos,onFrame,onState}){Object.assign(this,{videos,onFrame,onState});this.target=0;this.time=0;this.frames=new Map();this.pending=new Set();this.dead=false;this.canvas=document.createElement('canvas');this.canvas.className='story-canvas';this.canvas.setAttribute('aria-hidden','true');videos[0].before(this.canvas);this.ctx=this.canvas.getContext('2d',{alpha:false});this.mobile=matchMedia('(max-width:700px)').matches;this.folder=this.mobile?'frames-mobile':'frames-4k';this.resize=()=>{const r=this.canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(r.width*d);this.canvas.height=Math.round(r.height*d);this.lastDraw=-1};addEventListener('resize',this.resize);this.resize();this.tick=this.tick.bind(this)}
 start(){this.onState('loading');this.load(0);this.raf=requestAnimationFrame(this.tick)}
 seek(t){this.target=Math.max(0,Math.min(25,t))}
 async load(i){if(i<0||i>750||this.dead||this.frames.has(i)||this.pending.has(i)||this.pending.size>=6)return;this.pending.add(i);try{const r=await fetch(`assets/${this.folder}/${String(i+1).padStart(4,'0')}.webp`);if(!r.ok)throw Error('frame');const b=await createImageBitmap(await r.blob());if(this.dead)b.close();else this.frames.set(i,b)}catch{if(!this.frames.size)this.onState('error')}finally{this.pending.delete(i)}}
 tick(now){if(this.dead)return;const dt=Math.min(.05,(now-(this.last||now))/1000);this.last=now;const gap=this.target-this.time;const next=this.time+Math.sign(gap)*Math.min(Math.abs(gap)*(1-Math.exp(-dt*8)),dt*4);const f=next*30,i=Math.floor(f),dir=gap<0?-1:1;this.load(i);this.load(i+1);for(let j=1;j<(this.mobile?12:5);j++)this.load(i+j*dir);const a=this.frames.get(i),b=this.frames.get(i+1);if(a&&(b||i===750)){this.time=next;const w=this.canvas.width,h=this.canvas.height,c=this.ctx;if(this.lastDraw!==f){c.globalAlpha=1;c.fillStyle='#17121d';c.fillRect(0,0,w,h);const scale=(this.mobile?Math.max:Math.min)(w/a.width,h/a.height),dw=a.width*scale,dh=a.height*scale,x=(w-dw)*(this.mobile?this.focus(this.time):.5),y=(h-dh)/2;c.drawImage(a,x,y,dw,dh);if(b){c.globalAlpha=f-i;c.drawImage(b,x,y,dw,dh);c.globalAlpha=1}this.lastDraw=f;this.onFrame(this.time);this.onState('ready')}for(const [k,img] of this.frames)if(Math.abs(k-i)>(this.mobile?14:5)){img.close();this.frames.delete(k)}}this.raf=requestAnimationFrame(this.tick)}
 focus(t){const pts=[[0,.53],[3.8,.53],[5.2,.95],[6.6,.95],[8.2,.65],[10.5,.65],[12,.32],[13.7,.32],[15.3,.57],[18,.57],[20.7,.57],[22.5,.95],[24,.95],[25,.55]];for(let i=1;i<pts.length;i++){if(t<=pts[i][0]){const a=pts[i-1],b=pts[i],q=Math.max(0,(t-a[0])/(b[0]-a[0]));return a[1]+(b[1]-a[1])*q*q*(3-2*q)}}return .55}
 retry(){this.load(Math.floor(this.time*30))}
 destroy(){this.dead=true;cancelAnimationFrame(this.raf);removeEventListener('resize',this.resize);this.frames.forEach(b=>b.close());this.canvas.remove()}
}
